SELECT DATE_TRUNC('minute', make_timestamp(EventTime * 1000000)) AS M, COUNT(*) AS PageViews FROM hits WHERE CounterID = 62 AND make_date(EventDate) >= '2013-07-14' AND make_date(EventDate) <= '2013-07-15' AND IsRefresh = 0 AND DontCountHits = 0 GROUP BY DATE_TRUNC('minute', make_timestamp(EventTime * 1000000)) ORDER BY DATE_TRUNC('minute', make_timestamp(EventTime * 1000000)) LIMIT 10 OFFSET 1000;
